/**
 * Tailwind CSS v4 color palette.
 *
 * Hex values are the canonical Tailwind palette colors; OKLCH values are the
 * native Tailwind v4 theme values. RGB and HSL are derived from hex.
 *
 * This file is generated data - do not edit values by hand.
 */

export interface ColorShade {
  /** Scale name, e.g. 'red' */
  scale: string;
  /** Shade number, e.g. 500 */
  shade: number;
  /** Hex value, e.g. '#ef4444' */
  hex: string;
  /** RGB value, e.g. 'rgb(239 68 68)' */
  rgb: string;
  /** HSL value, e.g. 'hsl(0 84.2% 60.2%)' */
  hsl: string;
  /** OKLCH value (Tailwind v4 native), e.g. 'oklch(0.637 0.237 25.331)' */
  oklch: string;
  /** Tailwind utility class name, e.g. 'bg-red-500' */
  className: string;
}

export interface ColorScale {
  /** Scale name, e.g. 'red' */
  name: string;
  /** The 11 shades of the scale, from 50 to 950 */
  shades: ColorShade[];
}

export const COLOR_FORMATS = ['className', 'hex', 'rgb', 'hsl', 'oklch'] as const;

export type ColorFormat = (typeof COLOR_FORMATS)[number];

